1	import { describe, expect, it } from "vitest";
2	import { MODERATION_FLOW_ACTIONS } from "./actions.js";
3	import { MODERATION_FLOW_CONDITIONS } from "./conditions.js";
4	import { MODERATION_FLOW_TRIGGERS } from "./triggers.js";
5	import {
6		MODERATION_FLOW_ACTION_KEYS,
7		MODERATION_FLOW_CONDITION_KEYS,
8		MODERATION_FLOW_TRIGGER_KEYS,
9		type ModerationFlowParam
10	} from "./types.js";
11	import { buildDefaultParams, getAvailableActions, getAvailableConditions, validateFlowParams } from "./validate.js";
12	import { getAvailableVariables, MODERATION_FLOW_VARIABLES } from "./variables.js";
13	
14	// El catálogo lo consumen la dashboard Y el módulo, y ninguna de las dos puede
15	// detectar sola que está mal escrito: la dashboard pinta un control roto y el
16	// módulo ejecuta lo que le llegue. Estos tests son el único sitio donde una
17	// entrada mal copiada se cae, así que van sobre la COHERENCIA del catálogo, no
18	// sobre valores concretos (que cambiarán). Mismo criterio que
19	// `src/automation/catalog.test.ts`, del que este fichero es hermano.
20	
21	const allParams = (): Array<{ owner: string; param: ModerationFlowParam }> => [
22		...Object.values(MODERATION_FLOW_TRIGGERS).flatMap((d) => d.params.map((param) => ({ owner: `trigger:${d.key}`, param }))),
23		...Object.values(MODERATION_FLOW_CONDITIONS).flatMap((d) =>
24			d.params.map((param) => ({ owner: `condition:${d.key}`, param }))
25		),
26		...Object.values(MODERATION_FLOW_ACTIONS).flatMap((d) => d.params.map((param) => ({ owner: `action:${d.key}`, param })))
27	];
28	
29	describe("coherencia del catálogo", () => {
30		it("la clave del Record coincide con el `key` de cada definición", () => {
31			// Se rompe copiando y pegando una entrada y olvidando cambiar el `key` de
32			// dentro: el módulo busca por la clave del Record y la dashboard enseña la
33			// de dentro, así que la interfaz apunta a un bloque y se ejecuta otro.
34			for (const [key, def] of Object.entries(MODERATION_FLOW_TRIGGERS)) expect(def.key).toBe(key);
35			for (const [key, def] of Object.entries(MODERATION_FLOW_CONDITIONS)) expect(def.key).toBe(key);
36			for (const [key, def] of Object.entries(MODERATION_FLOW_ACTIONS)) expect(def.key).toBe(key);
37		});
38	
39		it("están definidas todas las claves declaradas", () => {
40			expect(Object.keys(MODERATION_FLOW_TRIGGERS).sort()).toEqual([...MODERATION_FLOW_TRIGGER_KEYS].sort());
41			expect(Object.keys(MODERATION_FLOW_CONDITIONS).sort()).toEqual([...MODERATION_FLOW_CONDITION_KEYS].sort());
42			expect(Object.keys(MODERATION_FLOW_ACTIONS).sort()).toEqual([...MODERATION_FLOW_ACTION_KEYS].sort());
43		});
44	
45		it("no hay parámetros repetidos dentro de un mismo bloque", () => {
46			const check = (name: string, params: ModerationFlowParam[]) => {
47				const keys = params.map((p) => p.key);
48				expect(new Set(keys).size, `${name} repite un parámetro`).toBe(keys.length);
49			};
50			for (const def of Object.values(MODERATION_FLOW_TRIGGERS)) check(`trigger:${def.key}`, def.params);
51			for (const def of Object.values(MODERATION_FLOW_CONDITIONS)) check(`condition:${def.key}`, def.params);
52			for (const def of Object.values(MODERATION_FLOW_ACTIONS)) check(`action:${def.key}`, def.params);
53		});
54	
55		it("todo `select` trae opciones y su default es una de ellas", () => {
56			for (const { owner, param } of allParams()) {
57				if (param.type !== "select") continue;
58				expect(param.options?.length, `${owner}.${param.key} no tiene opciones`).toBeGreaterThan(0);
59				if (param.default === undefined || param.default === null) continue;
60				const values = new Set(param.options?.map((o) => o.value));
61				const defaults = Array.isArray(param.default) ? param.default : [param.default];
62				for (const value of defaults) {
63					expect(values.has(String(value)), `${owner}.${param.key}: el default no está entre las opciones`).toBe(true);
64				}
65			}
66		});
67	
68		it("sólo los select llevan `multiple`, y sólo los textos `supportsVariables`", () => {
69			for (const { owner, param } of allParams()) {
70				if (param.multiple) expect(param.type, `${owner}.${param.key}`).toBe("select");
71				if (param.supportsVariables) {
72					expect(["text", "long_text"], `${owner}.${param.key}`).toContain(param.type);
73				}
74			}
75		});
76	
77		it("todo `pattern` declarado es una expresión regular válida", () => {
78			for (const { owner, param } of allParams()) {
79				if (!param.pattern) continue;
80				expect(() => new RegExp(param.pattern as string), `${owner}.${param.key}`).not.toThrow();
81			}
82		});
83	
84		it("los rangos declarados son coherentes", () => {
85			for (const { owner, param } of allParams()) {
86				if (param.min !== undefined && param.max !== undefined) {
87					expect(param.min, `${owner}.${param.key}`).toBeLessThanOrEqual(param.max);
88				}
89			}
90		});
91	
92		it("no hay etiquetas vacías: son el fallback cuando falta la traducción", () => {
93			for (const { owner, param } of allParams()) {
94				expect(param.label.trim(), `${owner}.${param.key}`).not.toBe("");
95			}
96			for (const def of [
97				...Object.values(MODERATION_FLOW_TRIGGERS),
98				...Object.values(MODERATION_FLOW_CONDITIONS),
99				...Object.values(MODERATION_FLOW_ACTIONS)
100			]) {
101				expect(def.label.trim(), def.key).not.toBe("");
102				expect(def.description.trim(), def.key).not.toBe("");
103			}
104		});
105	});
106	
107	describe("alcanzabilidad", () => {
108		// Un bloque que ningún disparador puede satisfacer sale en el catálogo, no
109		// aparece nunca en ningún selector y nadie se entera de que sobra.
110		it("toda condición se puede usar con algún disparador", () => {
111			for (const key of MODERATION_FLOW_CONDITION_KEYS) {
112				const usable = MODERATION_FLOW_TRIGGER_KEYS.some((t) => getAvailableConditions(t).some((c) => c.key === key));
113				expect(usable, `la condición ${key} es inalcanzable`).toBe(true);
114			}
115		});
116	
117		it("todo paso se puede usar con algún disparador", () => {
118			for (const key of MODERATION_FLOW_ACTION_KEYS) {
119				const usable = MODERATION_FLOW_TRIGGER_KEYS.some((t) => getAvailableActions(t).some((a) => a.key === key));
120				expect(usable, `el paso ${key} es inalcanzable`).toBe(true);
121			}
122		});
123	
124		it("todo disparador admite al menos un paso", () => {
125			for (const key of MODERATION_FLOW_TRIGGER_KEYS) {
126				expect(getAvailableActions(key).length, `el disparador ${key} no admite ningún paso`).toBeGreaterThan(0);
127			}
128		});
129	
130		it("«borrar el mensaje» sólo se ofrece cuando hay mensaje", () => {
131			expect(getAvailableActions("message_sent").map((a) => a.key)).toContain("delete_message");
132			expect(getAvailableActions("member_left").map((a) => a.key)).not.toContain("delete_message");
133		});
134	
135		it("«avisar»/«banear» no se ofrecen cuando el disparador no trae usuario", () => {
136			// `message_deleted` sólo aporta canal y mensaje: nadie a quien sancionar.
137			expect(getAvailableActions("message_deleted").map((a) => a.key)).not.toContain("warn_member");
138			expect(getAvailableActions("message_deleted").map((a) => a.key)).not.toContain("ban_member");
139			// pero sí trae mensaje, así que borrarlo (o purgar el canal) sigue disponible.
140			expect(getAvailableActions("message_deleted").map((a) => a.key)).toContain("delete_message");
141		});
142	
143		it("`getAvailableConditions`/`getAvailableActions` devuelven vacío para un disparador desconocido", () => {
144			expect(getAvailableConditions("no_existe")).toEqual([]);
145			expect(getAvailableActions("no_existe")).toEqual([]);
146		});
147	});
148	
149	describe("variables", () => {
150		it("no se ofrece {message} con un disparador que no trae mensaje", () => {
151			const tokens = getAvailableVariables("member_left").map((v) => v.key);
152			expect(tokens).toContain("{user}");
153			expect(tokens).not.toContain("{message}");
154		});
155	
156		it("las variables sin contexto están siempre", () => {
157			const always = MODERATION_FLOW_VARIABLES.filter((v) => v.requires === null).map((v) => v.key);
158			expect(always.length).toBeGreaterThan(0);
159			for (const key of MODERATION_FLOW_TRIGGER_KEYS) {
160				const tokens = getAvailableVariables(key).map((v) => v.key);
161				for (const token of always) expect(tokens, key).toContain(token);
162			}
163		});
164	
165		it("no hay tokens repetidos", () => {
166			const tokens = MODERATION_FLOW_VARIABLES.map((v) => v.key);
167			expect(new Set(tokens).size).toBe(tokens.length);
168		});
169	
170		it("`getAvailableVariables` devuelve vacío para un disparador desconocido", () => {
171			expect(getAvailableVariables("no_existe")).toEqual([]);
172		});
173	});
174	
175	describe("buildDefaultParams", () => {
176		const allDefs = () => [
177			...Object.values(MODERATION_FLOW_TRIGGERS),
178			...Object.values(MODERATION_FLOW_CONDITIONS),
179			...Object.values(MODERATION_FLOW_ACTIONS)
180		];
181	
182		it("ningún valor de fábrica está mal formado", () => {
183			// Un default inválido es especialmente traicionero: el bloque nace roto y
184			// el usuario ve un error en un campo que no ha tocado nunca.
185			//
186			// `missing_param` se excluye A PROPÓSITO: un bloque recién añadido con un
187			// campo obligatorio DEBE nacer vacío para que el formulario lo pinte y se
188			// lo pida. Lo que no puede es nacer con un valor con formato, rango u
189			// opción imposibles.
190			for (const def of allDefs()) {
191				const issues = validateFlowParams(buildDefaultParams(def.params), def.params, "params").filter(
192					(i) => i.code !== "missing_param"
193				);
194				expect(issues, `${def.key}: ${JSON.stringify(issues)}`).toEqual([]);
195			}
196		});
197	
198		it("sólo quedan sin rellenar los obligatorios que no declaran default", () => {
199			// El complemento del test anterior: sin esto, un default mal escrito que
200			// dejase el campo vacío se colaría disfrazado de «obligatorio sin default».
201			for (const def of allDefs()) {
202				const params = buildDefaultParams(def.params);
203				const missing = validateFlowParams(params, def.params, "params")
204					.filter((i) => i.code === "missing_param")
205					.map((i) => i.path.replace("params.", ""));
206				for (const key of missing) {
207					const param = def.params.find((p) => p.key === key);
208					expect(param?.required, `${def.key}.${key}`).toBe(true);
209					expect(param?.default, `${def.key}.${key} declara un default que no rellena nada`).toBeUndefined();
210				}
211			}
212		});
213	});
