				// Deja de ser obligatorio: con formato embed el texto puede ir todo en
				// el título y la descripción.
				required: false,
				label: "Mensaje",
				max: 2000,
				supportsVariables: true,
				default: ""
			},
			// Mismo orden que en `send_message`: primero el conmutador, luego el
			// control del modo elegido.
			{
				key: "image_mode",
				type: "select",
				variant: "chips",
