/**
 * Acciones que es SEGURO reintentar cuando Discord contesta con un 429.
 *
 * El criterio es la idempotencia, no la importancia: aplicar dos veces «dale el
 * rol X» deja exactamente el mismo estado que aplicarla una, así que reintentar
 * no puede hacer daño. Enviar un mensaje NO lo es — el reintento publica un
 * segundo mensaje, el usuario recibe el mismo aviso dos veces y no hay forma de
 * recogerlo.
 *
 * Por eso la lista es una ALTA EXPLÍCITA y no una exclusión: al añadir una
 * acción nueva al catálogo, lo seguro por defecto es no reintentarla. Si fuese
 * una lista de excluidas, olvidarse de dar de alta la acción nueva la haría
 * reintentable en silencio, que es el fallo caro.
 *
 * `wait`, `counter_set` y `run_automation` no salen a la red, así que no pueden
 * dar 429 y no pintan nada aquí.
 */
export const RETRYABLE_ACTIONS: ReadonlySet<AutomationActionType> = new Set([
	"add_reaction",
	"pin_message",
	// Idempotente por el lado de Discord: al segundo intento contesta 40033
	// («ya estaba publicado») y el ejecutor lo lee como éxito, así que un
	// reintento no puede publicar dos veces.
	"crosspost_message",
	"add_role",
	"remove_role",
	"set_nickname",
	"timeout_member",
	"set_slowmode",
	"set_channel_permission",
	"move_voice",
	"voice_mute",
	// Sólo leen: repetir «cuenta la gente en voz», «cuenta los miembros» o
	// «cuenta quién tiene un rol» dos veces deja exactamente el mismo estado
	// que una, así que reintentar no puede hacer daño.
	"count_voice_members",
	"count_members",
	"count_role_members"
]);

/** ¿Se puede reintentar esta acción sin duplicar efectos? */
export const isRetryableAction = (type: string): boolean =>
	RETRYABLE_ACTIONS.has(type as AutomationActionType);

import type { AutomationActionDef, AutomationActionType, AutomationParam } from "./types.js";

/**
 * Catálogo de ACCIONES.
 *
 * Todas tienen transporte gRPC en el gateway hoy — está comprobado contra los
 * `.proto`, no supuesto. Si añades una acción nueva, comprueba que su RPC existe
 * ANTES de meterla aquí: el catálogo es lo que la dashboard ofrece, y ofrecer una
 * acción sin transporte es prometer algo que falla en silencio en producción.
 */

/** Motivo para el registro de auditoría de Discord. */
const reasonParam: AutomationParam = {
	key: "reason",
	type: "text",
	required: false,
	label: "Motivo",
	hint: "Aparece en el registro de auditoría de Discord.",
	max: 512,
	supportsVariables: true,
	default: ""
};

/** Borrado diferido del mensaje que envía la acción. 0 = no se borra. */
const deleteAfterParam: AutomationParam = {
	key: "delete_after",
	type: "duration",
	required: false,
	label: "Borrarlo pasados",
	hint: "Segundos. 0 = no se borra.",
	min: 0,
	max: 86_400,
	default: 0
};

/**
 * Nombre de la variable donde la acción guarda el dato que recoge. Comparte
 * patrón y límites en toda la familia `stats`: cualquier acción que declare
 * una variable de flujo usa este mismo param, no uno propio por acción.
 */
const saveAsParam = (defaultName: string): AutomationParam => ({
	key: "save_as",
	type: "text",
	required: true,
	label: "Guardarlo en la variable",
	hint: "Luego se escribe {nombre} en cualquier campo de texto de las acciones de abajo.",
	pattern: "^[a-z0-9_]{1,32}$",
	min: 1,
	max: 32,
	default: defaultName
});

