	it("count_voice_members, count_members y count_role_members guardan su dato con el patrón compartido de save_as", () => {
		for (const key of ["count_voice_members", "count_members", "count_role_members"] as const) {
			const saveAs = AUTOMATION_ACTIONS[key].params.find((p) => p.key === "save_as");
			expect(saveAs, key).toBeDefined();
			expect(saveAs?.pattern, key).toBe("^[a-z0-9_]{1,32}$");
			expect(saveAs?.required, key).toBe(true);
		}
	});

	it("count_role_members declara roles, scope y save_as en ese orden, y se puede reintentar", () => {
		const def = AUTOMATION_ACTIONS.count_role_members;
		expect(def.params.map((p) => p.key)).toEqual(["roles", "scope", "save_as"]);

		const roles = def.params.find((p) => p.key === "roles");
		expect(roles?.type).toBe("role_list");
