// ─── Estadísticas ───────────────────────────────────────────────────────────
//
// No actúan sobre Discord —no hay canal que renombrar ni rol que dar—: leen
// un número y lo guardan en una variable de flujo (`save_as`) para que las
// acciones de detrás lo usen en sus campos de texto. Por eso no llevan
// `permission`.

count_voice_members: {
	key: "count_voice_members",
	category: "stats",
	label: "Contar personas en voz",
	description: "Cuenta cuánta gente hay en un canal de voz, o en todo el servidor.",
	requires: [],
	params: [
		{
			key: "channel",
			type: "channel",
			required: false,
			label: "Canal de voz",
			hint: "Vacío = todos los canales de voz del servidor."
		},
		saveAsParam("personas_en_voz")
	]
},

count_members: {
	key: "count_members",
	category: "stats",
	label: "Contar miembros del servidor",
	description: "El total de miembros, para un canal contador o un aviso de hito.",
	requires: [],
	params: [saveAsParam("miembros")]
},

count_connected_members: {
	key: "count_connected_members",
	category: "stats",
	label: "Contar miembros conectados",
	description:
		"Cuenta cuánta gente del servidor está en línea. Necesita el permiso de presencias, y cuenta a quien el bot haya visto conectarse desde que arrancó.",
	requires: [],
	params: [saveAsParam("miembros_conectados")]
},

count_role_members: {
	key: "count_role_members",
	category: "stats",
	label: "Contar personas con un rol",
	description:
		"Cuenta cuánta gente tiene alguno de los roles que elijas: en todo el servidor o sólo la conectada a voz.",
	requires: [],
	params: [
		{
			key: "roles",
			type: "role_list",
			required: true,
			label: "Roles",
			hint: "Cuenta a quien tenga ALGUNO de estos roles."
		},
		{
			key: "scope",
			type: "select",
			required: true,
			label: "Dónde contar",
			default: "guild",
			options: [
				{ value: "guild", label: "En todo el servidor" },
				{ value: "voice", label: "Sólo los conectados a voz" }
			]
		},
		saveAsParam("personas_con_rol")
	]
},

// ─── Flujo ──────────────────────────────────────────────────────────────────

wait: {
	key: "wait",
	category: "flow",
